import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine());
        String s = br.readLine();
        char[] c = s.toCharArray();
        int countV = 0, countK = 0, countOthers = 0;
        int[][] frequency = new int[n + 1][3];
        List<Integer>[] positions = new ArrayList[3];
        for (int i = 0; i < 3; i++) positions[i] = new ArrayList<>();
        int index = 0;
        for (char ch : c) {
            System.arraycopy(frequency[index], 0, frequency[index + 1], 0, 3);
            index++;
            switch (ch) {
                case 'V': frequency[index][0]++; countV++; positions[0].add(index); break;
                case 'K': frequency[index][1]++; countK++; positions[1].add(index); break;
                default: frequency[index][2]++; countOthers++; positions[2].add(index); break;
            }
        }
        int[][][][] memo = new int[countV + 1][countK + 1][countOthers + 1][3];
        for (int[][][] m3d : memo) for (int[][] m2d : m3d) for (int[] m1d : m2d) Arrays.fill(m1d, -1);
        System.out.println(compute(new int[]{0,0,0}, new int[]{countV, countK, countOthers}, positions, frequency, memo));
    }

    static int compute(int[] countUsed, int[] maxCount, List<Integer>[] pos, int[][] freq, int[][][][] dp) {
        int v = countUsed[0], k = countUsed[1], s = countUsed[2];
        int cv = maxCount[0], ck = maxCount[1], cs = maxCount[2];
        if (v == cv && k == ck && s == cs) return 0;
        if (dp[v][k][s][0] != -1) return dp[v][k][s][0]; // arbitrary index check
        int res = Integer.MAX_VALUE / 2;

        if (v < cv) {
            int p = pos[0].get(v);
            int moveCost = Math.max(freq[p][0] - v, 0) + Math.max(freq[p][1] - k, 0) + Math.max(freq[p][2] - s, 0) - 1;
            int[] newCount = Arrays.copyOf(countUsed, 3);
            newCount[0]++;
            res = Math.min(res, compute(newCount, maxCount, pos, freq, dp) + moveCost);
        }
        if (k < ck && (v != cv || true)) {
            int p = pos[1].get(k);
            int moveCost = Math.max(freq[p][0] - v, 0) + Math.max(freq[p][1] - k, 0) + Math.max(freq[p][2] - s, 0) - 1;
            int[] newCount = Arrays.copyOf(countUsed, 3);
            newCount[1]++;
            res = Math.min(res, compute(newCount, maxCount, pos, freq, dp) + moveCost);
        }
        if (s < cs) {
            int p = pos[2].get(s);
            int moveCost = Math.max(freq[p][0] - v, 0) + Math.max(freq[p][1] - k, 0) + Math.max(freq[p][2] - s, 0) - 1;
            int[] newCount = Arrays.copyOf(countUsed, 3);
            newCount[2]++;
            res = Math.min(res, compute(newCount, maxCount, pos, freq, dp) + moveCost);
        }
        return dp[v][k][s][0] = res; // assign at index 0
    }
}
